create table if not exists public.tenant_domains(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,hostname text not null unique,primary_domain boolean not null default false,verified boolean not null default false,created_at timestamptz not null default now());alter table public.tenant_domains enable row level security;create policy tenant_domains_read on public.tenant_domains for select to authenticated using(public.can_access_tenant(tenant_id,null));create policy tenant_domains_manage on public.tenant_domains for all to authenticated using(public.is_platform_staff(array['platform_owner','platform_admin']) or public.can_access_tenant(tenant_id,array['super_admin']::public.role_key[])) with check(public.is_platform_staff(array['platform_owner','platform_admin']) or public.can_access_tenant(tenant_id,array['super_admin']::public.role_key[]));
-- Analytics must always belong to a tenant.
update public.analytics_events set tenant_id='00000000-0000-4000-8000-000000000001' where tenant_id is null;alter table public.analytics_events alter column tenant_id set not null;create index if not exists analytics_tenant_time_idx on public.analytics_events(tenant_id,occurred_at desc);
drop policy if exists analytics_staff_read on public.analytics_events;create policy analytics_tenant_read on public.analytics_events for select to authenticated using(public.can_access_tenant(tenant_id,array['super_admin','admin']::public.role_key[]) or public.is_platform_staff(array['platform_owner','platform_admin','seo_manager','support_manager']));
create or replace function public.request_tenant_id() returns uuid language plpgsql stable security definer set search_path=public as $$declare h text;tid uuid;begin begin h:=split_part(coalesce((current_setting('request.headers',true)::jsonb->>'host'),''),':',1);exception when others then h:='';end;select tenant_id into tid from public.tenant_domains where lower(hostname)=lower(h) and verified=true limit 1;return coalesce(tid,'00000000-0000-4000-8000-000000000001'::uuid);end$$;
create or replace function public.record_analytics_event(p_event_type text,p_path text,p_visitor_id text default null,p_session_id text default null,p_referrer_host text default null,p_device_class text default null,p_metadata jsonb default '{}'::jsonb) returns void language plpgsql security definer set search_path=public as $$declare tid uuid:=public.request_tenant_id();begin if p_event_type not in ('page_view','engagement','conversion','web_vital') then raise exception 'invalid_event_type';end if;if p_path is null or length(p_path)>500 or p_path !~ '^/' or p_path like '/admin%' or p_path like '/api/%' then return;end if;if p_visitor_id is not null and length(p_visitor_id)>100 then raise exception 'invalid_visitor_id';end if;if p_session_id is not null and length(p_session_id)>100 then raise exception 'invalid_session_id';end if;if p_referrer_host is not null and length(p_referrer_host)>255 then p_referrer_host=left(p_referrer_host,255);end if;if p_device_class is not null and p_device_class not in ('mobile','tablet','desktop','other') then p_device_class='other';end if;if pg_column_size(coalesce(p_metadata,'{}'::jsonb))>4096 then p_metadata='{}'::jsonb;end if;insert into public.analytics_events(tenant_id,event_type,path,visitor_id,session_id,referrer_host,device_class,metadata) values(tid,p_event_type,left(p_path,500),nullif(p_visitor_id,''),nullif(p_session_id,''),nullif(p_referrer_host,''),p_device_class,coalesce(p_metadata,'{}'::jsonb));end$$;
create or replace function public.analytics_daily_summary(p_tenant_id uuid,p_days integer default 30) returns table(day date,views bigint,visitors bigint,sessions bigint) language plpgsql stable security definer set search_path=public as $$begin if not public.can_access_tenant(p_tenant_id,array['super_admin','admin']::public.role_key[]) and not public.is_platform_staff(null) then raise exception 'forbidden';end if;return query select d::date,count(e.id) filter(where e.event_type='page_view')::bigint,count(distinct e.visitor_id)::bigint,count(distinct e.session_id)::bigint from generate_series(current_date-greatest(1,least(p_days,365))+1,current_date,'1 day') d left join public.analytics_events e on e.tenant_id=p_tenant_id and e.occurred_at>=d and e.occurred_at<d+interval '1 day' group by d order by d;end$$;
create or replace function public.analytics_top_pages(p_tenant_id uuid,p_days integer default 30,p_limit integer default 10) returns table(path text,views bigint,visitors bigint) language plpgsql stable security definer set search_path=public as $$begin if not public.can_access_tenant(p_tenant_id,array['super_admin','admin']::public.role_key[]) and not public.is_platform_staff(null) then raise exception 'forbidden';end if;return query select e.path,count(*)::bigint,count(distinct e.visitor_id)::bigint from public.analytics_events e where e.tenant_id=p_tenant_id and e.event_type='page_view' and e.occurred_at>=now()-make_interval(days=>greatest(1,least(p_days,365))) group by e.path order by count(*) desc limit greatest(1,least(p_limit,50));end$$;
create or replace function public.analytics_period_summary(p_tenant_id uuid,p_days integer default 30) returns table(views bigint,visitors bigint,sessions bigint,conversions bigint) language plpgsql stable security definer set search_path=public as $$begin if not public.can_access_tenant(p_tenant_id,array['super_admin','admin']::public.role_key[]) and not public.is_platform_staff(null) then raise exception 'forbidden';end if;return query select count(*) filter(where event_type='page_view')::bigint,count(distinct visitor_id)::bigint,count(distinct session_id)::bigint,count(*) filter(where event_type='conversion')::bigint from public.analytics_events where tenant_id=p_tenant_id and occurred_at>=now()-make_interval(days=>greatest(1,least(p_days,365)));end$$;
grant execute on function public.analytics_daily_summary(uuid,integer),public.analytics_top_pages(uuid,integer,integer),public.analytics_period_summary(uuid,integer) to authenticated;
